168:async function collectEvidenceErrors(root, item, plan) {
169:  const errors = [];
170:  const paths = await workItemPaths(root, item.id);
171:  let raw = "";
172:  try {
173:    raw = await readFile(paths.evidence, "utf8");
174:  } catch (error) {
175:    if (error.code !== "ENOENT") throw error;
176:  }
177:
178:  const events = [];
179:  const byId = new Map();
180:  for (const [index, line] of raw.split(/\r?\n/).entries()) {
181:    if (!line.trim()) continue;
182:    let event;
183:    try {
184:      event = JSON.parse(line);
185:    } catch (error) {
186:      errors.push(`evidence.jsonl:${index + 1} 不是有效 JSON：${error.message}`);
187:      continue;
188:    }
189:    if (event.schemaVersion !== 1 || !event.id?.trim() || event.workItemId !== item.id) {
190:      errors.push(`evidence.jsonl:${index + 1} 基本结构或 workItemId 无效。`);
191:      continue;
192:    }
193:    if (!EVIDENCE_KINDS.includes(event.kind) || !event.summary?.trim() || !event.timestamp?.trim()) {
194:      errors.push(`evidence.jsonl:${index + 1} kind、summary 或 timestamp 无效。`);
195:    }
196:    if (event.kind !== "command" && !RESULT_STATUSES.includes(event.status)) {
197:      errors.push(`evidence.jsonl:${index + 1} 结果状态无效。`);
198:    }
199:    if (byId.has(event.id)) errors.push(`evidence.jsonl 包含重复 ID：${event.id}`);
200:    byId.set(event.id, event);
201:    events.push(event);
202:  }
203:
204:  const assertReferences = (references, { kind, taskId = null, label }) => {
205:    for (const reference of references) {
206:      const event = byId.get(reference);
207:      if (!event) {
208:        errors.push(`${label} 引用不存在的证据：${reference}`);
209:        continue;
210:      }
211:      if (event.kind !== kind || (event.taskId ?? null) !== taskId) {
212:        errors.push(`${label} 证据类型或 taskId 不匹配：${reference}`);
213:      }
214:    }
215:  };
216:
217:  for (const kind of ["verification", "review", "acceptance", "analysis", "documentation"]) {
218:    const result = item[kind];
219:    assertReferences(result.evidence, { kind, label: `工作项 ${kind}` });
220:    if (kind === "verification" && Array.isArray(result.stages) && result.stages.length > 0) {
221:      // 分阶段流水线：逐子阶段比对状态，并核对聚合状态。
222:      for (const stage of result.stages) {
223:        const latestStage = events.findLast(
224:          (event) => event.kind === "verification" && (event.taskId ?? null) === null && event.stage === stage.stage,
225:        );
226:        if (!latestStage || latestStage.status !== stage.status) {
227:          errors.push(`验证子阶段 ${stage.stage} 状态与最新证据不一致。`);
228:        }
229:        if (stage.command !== undefined && stage.command !== null) {
230:          const commandEvent = byId.get(stage.command);
231:          if (!commandEvent || commandEvent.kind !== "command") {
232:            errors.push(`验证子阶段 ${stage.stage} 的命令证据不存在或类型错误：${stage.command}`);
233:          } else if (stage.status === "pass" && commandEvent.status !== "pass") {
234:            errors.push(`验证子阶段 ${stage.stage} 记为 pass 但其命令证据未通过。`);
235:          }
236:        }
237:      }
238:      const expected = aggregateVerificationStatus(result.stages, requiredVerificationStages(item));
239:      if (result.status !== expected) {
240:        errors.push(`verification 聚合状态与子阶段不一致，应为 ${expected}。`);
241:      }
242:      continue;
243:    }
244:    const latest = events.findLast((event) => event.kind === kind && (event.taskId ?? null) === null);
245:    if (result.status !== "pending" && (!latest || latest.status !== result.status)) {
246:      errors.push(`工作项 ${kind} 状态与最新证据不一致。`);
247:    }
248:    if (kind === "review" && latest && Boolean(latest.independent) !== result.independent) {
249:      errors.push("工作项 review 的独立复核标记与最新证据不一致。");
250:    }
251:  }
252:
253:  for (const task of plan?.tasks || []) {
254:    for (const reference of task.evidence) {
255:      const event = byId.get(reference);
256:      if (!event) {
257:        errors.push(`任务 ${task.id} 引用不存在的证据：${reference}`);
258:      } else if (event.taskId !== task.id || !["verification", "review"].includes(event.kind)) {
259:        errors.push(`任务 ${task.id} 的证据类型或 taskId 不匹配：${reference}`);
260:      }
261:    }
262:    for (const [kind, statusField] of [["verification", "verificationStatus"], ["review", "reviewStatus"]]) {
263:      const latest = events.findLast((event) => event.taskId === task.id && event.kind === kind);
264:      if (task[statusField] !== "pending" && (!latest || latest.status !== task[statusField])) {
265:        errors.push(`任务 ${task.id} 的 ${statusField} 与最新证据不一致。`);
266:      }
267:    }
268:  }
269:  return errors;
270:}
